mapper.select:
select distinct a.id,a.code,a.associated_no,a.department_id,a.status,a.type_id,a.warehouse_id,a.affirm_time,a.affirm_name,a.create_name,a.create_time,a.update_name,a.update_time,a.note
from pms_material_requisition a left join pms_material_requisition_info b on b.material_requisition_id = a.id

    a.del_flag = 0

        and a.code LIKE CONCAT('%',#{dto.code},'%')


        and a.department_id = #{dto.departmentId}


        and a.type_id = #{dto.typeId}


        and a.status = #{dto.status}


        and b.material_code LIKE CONCAT('%',#{dto.materialCode},'%')


        and a.create_time between #{dto.startCreateTime} and #{dto.endCreateTime}


        and a.associated_no = #{dto.associatedNo}


Order By create_time DESC

SELECT pmri.material_id AS materialId, SUM(pmri.receive_quantity) AS receiveQuantity, pmri.require_date AS requireDate FROM pms_material_requisition_info pmri LEFT JOIN pms_material_requisition pmr ON pmri.material_requisition_id = pmr.id
pmr.del_flag = 0
and pmr.department_id in
#{item}
and pmri.require_date between #{startTime} AND #{endTime}
GROUP BY requireDate, materialId

